import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class MakeDeclaredNamesUnique_enterScope_TriageGen1Test {

    @Mock private NodeTraversal mockTraversal;
    @Mock private Node mockScopeRoot;
    @Mock private Renamer mockRootRenamer;
    @Mock private Renamer mockChildRenamer;
    @Mock private Node mockFunctionNode;
    @Mock private Node mockBlockNode;

    private MakeDeclaredNamesUnique makeDeclaredNamesUnique;

    @Before
    public void setUp() throws Exception {
        // We use reflection or a subclass to inject the protected/internal fields 
        // since we can't access nameStack or rootRenamer directly in a standard way.
        // For this test, we assume we are testing the logic of the provided snippet.
        makeDeclaredNamesUnique = spy(new MakeDeclaredNamesUnique(mock(ErrorReporter.class)));

        // Injecting private fields via reflection to simulate the state
        setInternalState(makeDeclaredNamesUnique, "rootRenamer", mockRootRenamer);
        setInternalState(makeDeclaredNamesUnique, "nameStack", new java.util.ArrayDeque<>());
    }

    @Test
    public void testEnterScope_GlobalScopeWithContextualRenamerFails() {
        when(mockTraversal.getScopeRoot()).thenReturn(mockScopeRoot);
        when(mockScopeRoot.getType()).thenReturn(Token.FUNCTION);

        // Setup rootRenamer as ContextualRenamer
        ContextualRenamer contextualRenamer = mock(ContextualRenamer.class);
        setInternalState(makeDeclaredNamesUnique, "rootRenamer", contextualRenamer);

        // Precondition 1: nameStack is empty AND root is FUNCTION AND rootRenamer is Contextual
        assertThrows(IllegalStateException.class, () -> {
            makeDeclaredNamesUnique.enterScope(mockTraversal);
        });
    }

    @Test
    public void testEnterScope_GlobalScopeNotFunctionPasses() {
        when(mockTraversal.getScopeRoot()).thenReturn(mockScopeRoot);
        when(mockScopeRoot.getType()).thenReturn(Token.BLOCK);
        when(mockTraversal.inGlobalScope()).thenReturn(true);

        // Mock findDeclaredNames to avoid NPE
        doNothing().when(makeDeclaredNamesUnique).findDeclaredNames(any(), eq(null), any());

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        verify(makeDeclaredNamesUnique).findDeclaredNames(eq(mockScopeRoot), eq(null), eq(mockRootRenamer));
    }

    @Test
    public void testEnterScope_GlobalScopeNotFunctionFailsIfNoGlobal() {
        when(mockTraversal.getScopeRoot()).thenReturn(mockScopeRoot);
        when(mockScopeRoot.getType()).thenReturn(Token.BLOCK);
        when(mockTraversal.inGlobalScope()).thenReturn(false);

        assertThrows(IllegalStateException.class, () -> {
            makeDeclaredNamesUnique.enterScope(mockTraversal);
        });
    }

    @Test
    public void testEnterScope_FunctionScopeUsesStack() throws Exception {
        // Setup Stack
        java.util.Deque<Renamer> stack = new java.util.ArrayDeque<>();
        stack.push(mockChildRenamer);
        setInternalState(makeDeclaredNamesUnique, "nameStack", stack);

        when(mockTraversal.getScopeRoot()).thenReturn(mockScopeRoot);
        when(mockScopeRoot.getType()).thenReturn(Token.FUNCTION);

        // Mocking the function structure: function() { param1; param2; body; }
        // Node: FUNCTION -> [FIRST_CHILD -> [PARAMS -> [p1, p2]], LAST_CHILD -> BODY]
        Node mockFirstChild = mock(Node.class);
        Node mockParams = mock(Node.class);
        Node mockParam1 = mock(Node.class);
        Node mockParam2 = mock(Node.class);
        Node mockBody = mock(Node.class);

        when(mockScopeRoot.getFirstChild()).thenReturn(mockFirstChild);
        when(mockFirstChild.getNext()).thenReturn(mockParams);
        when(mockParams.getFirstChild()).thenReturn(mockParam1);
        when(mockParam1.getNext()).thenReturn(mockParam2);
        when(mockParam2.getNext()).thenReturn(null);
        when(mockScopeRoot.getLastChild()).thenReturn(mockBody);

        when(mockParam1.getString()).thenReturn("p1");
        when(mockParam2.getString()).thenReturn("p2");

        doNothing().when(makeDeclaredNamesUnique).findDeclaredNames(eq(mockBody), eq(null), eq(mockChildRenamer));

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        verify(mockChildRenamer).addDeclaredName("p1");
        verify(mockChildRenamer).addDeclaredName("p2");
        verify(makeDeclaredNamesUnique).findDeclaredNames(eq(mockBody), eq(null), eq(mockChildRenamer));
    }

    @Test
    public void testEnterScope_NonFunctionScopeUsesStack() throws Exception {
        java.util.Deque<Renamer> stack = new java.util.ArrayDeque<>();
        stack.push(mockChildRenamer);
        setInternalState(makeDeclaredNamesUnique, "nameStack", stack);

        when(mockTraversal.getScopeRoot()).thenReturn(mockScopeRoot);
        when(mockScopeRoot.getType()).thenReturn(Token.BLOCK);

        doNothing().when(makeDeclaredNamesUnique).findDeclaredNames(eq(mockScopeRoot), eq(null), eq(mockChildRenamer));

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        verify(makeDeclaredNamesUnique).findDeclaredNames(eq(mockScopeRoot), eq(null), eq(mockChildRenamer));
    }

    /**
     * Helper to set private fields since the class doesn't provide setters for the test.
     */
    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
